904833d5993eef17","8ffd62d7ee5c5ebff9d63aea826c4c7fb2086adc2c20378508b049ef73bd9dd9","postgres","{postgres=X/postgres}",["search_path=pg_catalog, public"],"s",true,false,false,false,"sql","","","text","u","f"]},{"signature":"public.hotel_v2_seven_arches_reviewed_pricing_current_state()","meta":["daa90ae3ec5515f22f8be8034276738d135bf3839bdd539dde99fe16636889c8","6658273707d91f56172b4946c3b1560da7b44c80dd40afe4df87f3e8ff655ab3","postgres","{postgres=X/postgres}",["search_path=pg_catalog, public"],"s",true,false,false,false,"sql","","","jsonb","u","f"]},{"signature":"public.hotel_v2_seven_arches_reviewed_pricing_oracle()","meta":["50fee36eb4e4c7a11ad0baf0188a9f2042bde3678c5d835b3e8b7ece992ebfef","1b4b1497db1b0e4f07a550c4a5475c044f517041cc75b878331d3039104046a1","postgres","{postgres=X/postgres}",["search_path=pg_catalog, public"],"s",true,false,false,false,"sql","","","jsonb","u","f"]},{"signature":"public.hotel_v2_seven_arches_reviewed_pricing_receipt_chain_is_exact()","meta":["ca914b81c1b0d22ad186669010b27b13c946949e73bfc84ce8065bea037e5424","cea8de2e25ff83aa1834cbb6c1ca4b78e73de145fc07f32234136da9d9a95649","postgres","{postgres=X/postgres}",["search_path=pg_catalog, public"],"s",true,false,false,false,"plpgsql","","","boolean","u","f"]},{"signature":"public.is_current_user_admin()","meta":["581f1801056e5aee65c0144151b41dea41910d2c8e22639873ff659487e8a255","b22b4cf0fc9af5cdf67e880eb404de038dcea9cfa9220e11541da17e45720899","postgres","{anon=X/postgres,authenticated=X/postgres,postgres=X/postgres,service_role=X/postgres}",["search_path=public"],"s",true,false,false,false,"plpgsql","","","boolean","u","f"]}]'::jsonb) LOOP
  IF (SELECT (SELECT jsonb_build_array(encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),
