 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN (''''hotels_lifecycle_private'''',''''hotel_stripe_connect_private'''') AND c.relkind IN (''''r'''',''''p'''')),
