 EXECUTE 'CREATE FUNCTION hotels_partner_read_once_private.read_9e863cbe183fb1f3(p_read_context jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER  SET search_path TO ''pg_catalog'', ''public'' AS ''
DECLARE s jsonb; flags jsonb;
BEGIN
 s:=(CASE WHEN (p_read_context#>>ARRAY[''''hotels_lifecycle_private.chain_state'''',''''is_null''''])::boolean THEN NULL::jsonb ELSE p_read_context#>ARRAY[''''hotels_lifecycle_private.chain_state'''',''''value''''] END); flags:=(CASE WHEN (p_read_context#>>ARRAY[''''hotels_lifecycle_private.actual_flags'''',''''is_null''''])::boolean THEN NULL::jsonb ELSE p_read_context#>ARRAY[''''hotels_lifecycle_private.actual_flags'''',''''value''''] END);
 IF (SELECT count(*) FROM public.site_settings)<>1
 OR flags IS DISTINCT FROM ((s->''''state'''')-''''public_booking_enabled'''')
 OR EXISTS(SELECT 1 FROM jsonb_each(flags) e WHERE jsonb_typeof(e.value)<>''''boolean'''')
 THEN RAISE EXCEPTION ''''hotels_lifecycle_flag_state_drift''''; END IF;
 RETURN jsonb_build_object(''''contract_version'''',''''hotels_v2_capability_lifecycle_v1'''',''''version'''',s->''''version'''',
 ''''feature_flags'''',flags,''''public_booking_enabled'''',false,''''architecture'''',''''legacy'''',''''expected_public_change'''',false,''''audit_chain_exact'''',true);
END '';
