    (''''public.hotel_v2_h3_1p_parity_snapshot(uuid)''''),
    (''''public.hotel_v2_h3_2b_hash(jsonb)''''),
    (''''public.hotel_v2_external_calendar_worker_hash(jsonb)''''),
    (''''public.hotel_v2_seven_arches_payment_policy_lineage_is_exact()'''')
